      .details-panel {
        display: flex;
        min-width: 0;
        flex-direction: column;
        justify-content: space-between;
        gap: 2rem;
        border-left: 1px solid var(--border);
        background: var(--surface);
        padding: clamp(1.5rem, 4vw, 2.5rem);
