        font-size: 1.05rem;
      }

      .meta-list {
        display: grid;
        gap: 0.8rem;
        margin: 0;
      }

      .meta-row {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-bottom: 1px solid var(--border);
        padding-bottom: 0.8rem;
      }

      .meta-row dt {
        color: var(--muted);
        font-weight: 600;
