      .meta-row dd {
        margin: 0;
        text-align: right;
        overflow-wrap: anywhere;
      }

      .actions,
      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      button {
        min-height: 2.75rem;
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0.75rem 1rem;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition:
          background-color 160ms ease,
          border-color 160ms ease,
          color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:focus-visible,
      a:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .button-secondary {
        border-color: var(--border);
        background: var(--surface);
        color: var(--text);
      }

      .button-secondary:hover {
        border-color: var(--text);
        background: var(--surface-subtle);
      }

      .button-danger {
        background: var(--danger);
        color: #ffffff;
      }

      .button-danger:hover {
        background: var(--danger-hover);
      }

      dialog {
        width: min(92vw, 32rem);
        border: 0;
        border-radius: 1.5rem;
        padding: 0;
        color: var(--text);
        background: var(--surface);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: #111827b8;
      }

      .dialog-content {
        padding: clamp(1.25rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        margin-bottom: 1rem;
        place-items: center;
        border-radius: 1rem;
        background: #fee2e2;
        color: var(--danger);
      }

      .dialog-content h2 {
        margin: 0;
        font-size: clamp(1.5rem, 6vw, 2rem);
        line-height: 1.1;
        letter-spacing: -0.04em;
      }

      .dialog-content p {
        margin: 0.9rem 0 1.4rem;
        color: var(--muted);
      }

      .status {
        min-height: 1.5rem;
        margin-top: 1rem;
        color: var(--danger);
        font-weight: 700;
      }

      @media (max-width: 760px) {
        .card {
          grid-template-columns: 1fr;
